def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    valid_mask = bins >= item
    return np.where(valid_mask, -(bins - item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    valid_mask = bins >= item
    fill_ratio = item / bins
    return np.where(valid_mask, -np.abs(fill_ratio - 0.8), -np.inf)

